function usePlay(){const {saved,setSaved}=useStore(),nav=useNavigation<Nav>();return (target?:unknown)=>{const peerId=typeof target==='string'?target:undefined;if(saved.launch){if(palFindingProgress(saved).eligible&&!palFindingProgress(saved).canPlay){nav.navigate('LaunchUnlock');return;}try{const next=prepareLaunchTopics(saved,new Date());setSaved(next);if(hasDailyProgress(next.daily))nav.navigate('Play',{index:resumeDailyIndex(next.daily)});else nav.navigate('Categories',{peerId});}catch(e){Alert.alert('Your plays',(e as Error).message);}return;}const daily=prepareDemoPlay(saved.daily);setSaved(s=>({...s,daily,social:{...s.social,focusCountryId:null}}));if(!hasDailyProgress(daily)){if(daily.active)setSaved(s=>({...s,daily:{...daily,active:null}}));if(dailyStatus(daily).kind==='ready')nav.navigate('Categories');else nav.navigate('Main',{screen:'Home'});return;}try{const next=beginDaily(daily,(saved.profile??FALLBACK_PROFILE).ageBand);setSaved(s=>({...s,daily:next}));nav.navigate('Play',{index:resumeDailyIndex(next)});}catch{nav.navigate('Main',{screen:'Home'});}};}
