function MainTabs(){
 const {saved,now}=useStore(),insets=useSafeAreaInsets(),nav=useNavigation<Nav>(),profile=saved.profile??FALLBACK_PROFILE,privatePhotos=profile.ageBand==='10-12';
 return <Tab.Navigator initialRouteName="Home" tabBar={props=><NativeNavigationBar {...props} avatar={profile.avatar} count={privatePhotos?saved.photos.photos.filter(p=>p.ageBand===profile.ageBand).length:worldStats(saved).friends} privatePhotos={privatePhotos} taskCount={photoMonthProgress(saved,now).count}/>} screenOptions={{
  headerStyle:{backgroundColor:PAPER},headerTitle:()=><Brand dark/>,headerTitleAlign:'left',headerTitleContainerStyle:{paddingLeft:8},headerShadowVisible:false,headerBackground:()=><NativeHeaderBackdrop/>,
  headerRight:()=><View style={{flexDirection:'row',alignItems:'center',gap:9,paddingRight:16}}>{saved.launch&&!privatePhotos&&<Pressable accessibilityRole="button" onPress={()=>nav.navigate('LaunchUnlock',{demo:true})} style={{minWidth:44,minHeight:44,paddingHorizontal:5,alignItems:'center',justifyContent:'center'}}><Text style={{fontSize:12,lineHeight:18,fontWeight:'500',color:'#C8BEFF',textDecorationLine:'underline'}}>Demo</Text></Pressable>}{!privatePhotos&&(saved.launch?<Pressable accessibilityRole="button" accessibilityLabel="Notifications" onPress={()=>nav.navigate('CityUpdates')} style={{width:44,height:44,alignItems:'center',justifyContent:'center'}}><Ionicons name="notifications-outline" size={22} color={BLUE}/>{(cityMeetupNotice(saved.cityMeetup,now)?.unread||(palFindingProgress(saved).canPlay&&palUpdates(saved,now).some(n=>!n.read)))&&<View style={{position:'absolute',right:8,top:7,width:6,height:6,borderRadius:4,backgroundColor:'#C8BEFF'}}/>}</Pressable>:<NativeUpdatesBell state={saved} now={now} onOpen={()=>nav.navigate('CityUpdates')}/>)}</View>,
  tabBarStyle:{height:72+Math.max(8,insets.bottom),backgroundColor:PAPER,borderTopWidth:0},
 }}>
  <Tab.Screen name="Home" component={HomeScreen} options={{title:'Explore'}}/>
  <Tab.Screen name="Cities" component={PassportScreen} options={{title:'Cities'}}/><Tab.Screen name="Tasks" component={TasksScreen} options={{title:'Task'}}/>
  <Tab.Screen name="Favorites" component={FavoritesScreen} options={{title:'Favs'}}/>
  <Tab.Screen name="Profile" component={ProfileScreen} options={{title:'Profile'}}/>
 </Tab.Navigator>;
}

function WelcomeScreen(){const nav=useNavigation<Nav>();return <NativeWelcome onStart={()=>nav.navigate('Setup')}/>;}

function AvatarScreen(){const {setup,setSetup}=useStore(),nav=useNavigation<Nav>();return <NativeAvatarPicker value={setup.avatar} onDone={avatar=>{setSetup(v=>({...v,avatar}));nav.goBack();}}/>;}
function SetupScreen(){
 const {setup,setSetup,saved,setSaved}=useStore(),nav=useNavigation<Nav>();
 const [photoBusy,setPhotoBusy]=useState(false),[saving,setSaving]=useState(false),[error,setError]=useState('');
 async function save(){
  if(photoBusy||saving)return;if(!saved.profile&&(!setup.city?.trim()||!setup.country?.trim())){setError('Add your city and country.');return;}setSaving(true);setError('');
  try{
   const raw=await AsyncStorage.getItem(KEY),fresh=readPreview(JSON.parse(raw??'null')),s=fresh.profile?fresh:saved;
   const photo=readProfilePhoto(setup.photo,setup.ageBand),profile={name:setup.name,avatar:setup.avatar,ageBand:setup.ageBand,...readProfileLocation(setup),...(photo?{photo}:{})};
   const updated={...s,profile,...(s.profile?.ageBand!==setup.ageBand?{answers:{},completed:false,saved:[],reactions:{},daily:{...s.daily,active:null},visits:hideAllCityVisits(s.visits),photos:{...privatizeCityPhotos(s.photos),...(!s.profile?{activityStartedMonth:cityPhotoMonth(new Date())}:{})}}:{})};
   const next=s.profile?updated:enableLaunch(updated);await AsyncStorage.setItem(KEY,JSON.stringify(next));setSaved(next);
   nav.reset({index:0,routes:[{name:'Main',params:{screen:saved.profile?'Profile':'Home'}}]});
  }catch{setError('Couldn’t save. Free some device storage or try a smaller photo.');}finally{setSaving(false);}
 }
 return <Screen><NativeProfileSetup profile={setup} editing={!!saved.profile} busy={photoBusy||saving} error={error} onAvatar={()=>nav.navigate('Avatar')} onLocation={(field,value)=>setSetup(s=>({...s,[field]:value}))} onPhoto={photo=>setSetup(s=>({...s,photo}))} onBusy={setPhotoBusy} onSave={()=>void save()}/></Screen>;
}
function HomeScreen(){const {saved,now}=useStore(),nav=useNavigation<Nav>(),play=usePlay(),launch=useLaunchActions(),openCheckIn=useCityMeetupOpen();if(palSummaries(saved).length>0)return <PalsScreen/>;if(saved.launch&&palFindingProgress(saved).canPlay)return <NativeGlobalHome state={saved} now={now} onPlay={play} onTasks={()=>nav.navigate('Main',{screen:'Tasks'})} onCheckIn={()=>openCheckIn()}/>;if(saved.launch)return <NativeLaunchHome state={saved} now={now} onCheckIn={()=>openCheckIn()} onResetPreview={()=>void launch.safe(resetPalUnlock)} onPlay={play} onInvite={()=>void launch.invite()} onGuide={countryId=>nav.navigate('Guide',{countryId})} onTasks={()=>nav.navigate('Main',{screen:'Tasks'})} onPostcards={()=>nav.navigate('LaunchPostcards')} onEdit={()=>nav.navigate('Main',{screen:'Profile'})}/>;if(saved.profile?.ageBand!=='10-12')return palSummaries(saved).length?<PalsScreen/>:<NativeExploreIntro state={saved} now={now} onPlay={play} onSchedule={()=>nav.navigate('Schedule')}/>;return <NativePassportHome game={saved.daily} passport={saved.passport} social={saved.social} blocked={saved.blocked} profile={saved.profile??FALLBACK_PROFILE} now={now} focused onPlay={play} onSchedule={()=>nav.navigate('Schedule')} onShare={()=>nav.navigate('Share')} onPassport={()=>nav.navigate('Main',{screen:'Cities'})}/>;}
function TasksScreen(){const {saved,now}=useStore(),nav=useNavigation<Nav>();if(saved.launch)return <NativeLaunchTask state={saved} now={now} onCapture={()=>nav.navigate('Camera')} onPhotos={()=>nav.navigate('LaunchMoments')}/>;return <NativeMonthlyTasks state={saved} now={now} onCapture={()=>nav.navigate('Camera')}/>;}
function PassportScreen(){const {saved}=useStore(),nav=useNavigation<Nav>(),play=usePlay(),openCheckIn=useCityMeetupOpen();if(palSummaries(saved).length>0||saved.launch&&palFindingProgress(saved).canPlay)return <NativeGlobalCities state={saved} onPal={peerId=>nav.navigate('Pal',{peerId})} onCity={countryId=>nav.navigate('Country',{countryId})} onPhotos={countryId=>nav.navigate('CityPhotos',{countryId})} onPlay={play} onCheckIn={()=>openCheckIn()} onGuide={countryId=>nav.navigate('Guide',{countryId})}/>;if(saved.launch)return <NativeLaunchCities state={saved} onCheckIn={()=>openCheckIn()} onGuide={countryId=>nav.navigate('Guide',{countryId})} onEdit={()=>nav.navigate('Main',{screen:'Profile'})} onPostcards={()=>nav.navigate('LaunchPostcards')}/>;return <NativeCitiesCollection state={saved} onCountry={countryId=>nav.navigate('Country',{countryId})} onPhotos={countryId=>nav.navigate('CityPhotos',{countryId})} onPlay={play}/>;}
