 const {saved,setSaved,now}=useStore(),profile=saved.profile??FALLBACK_PROFILE,focused=useIsFocused(),locked=!!saved.launch&&palFindingProgress(saved).eligible&&!palFindingProgress(saved).canPlay,status=dailyStatus(saved.daily,now);
 useEffect(()=>{if(!focused||!saved.launch)return;if(locked)navigation.replace('LaunchUnlock');else if(hasDailyProgress(saved.daily))navigation.replace('Play',{index:resumeDailyIndex(saved.daily)});else if(status.kind!=='ready')navigation.popTo('Main',{screen:'Home'});},[focused,locked,status.kind,saved.daily.active,navigation]);
