function PlayScreen({route,navigation}:NativeStackScreenProps<Root,'Play'>){const {saved,setSaved,ideas,setIdeas,now}=useStore(),profile=saved.profile??FALLBACK_PROFILE,index=Math.max(0,Math.min(route.params.index,2)),preparing=!!route.params.invite&&!!saved.launch?.preparation,questions=preparing?invitePreparationQuestions(saved):activeQuestions(saved.daily,profile.ageBand),q=questions[index],answer=preparing?saved.launch!.preparation!.answers[index]:saved.daily.active?.answers[q?.id]??'',usage=weeklyIdeas(ideas,now),idea=usage.revealed[q?.id],remaining=3-usage.used;const status=preparing?{kind:'ready' as const,remainingMs:0}:dailyStatus(saved.daily,now),finishing=useRef(false),focused=useIsFocused(),locked=!!saved.launch&&!preparing&&palFindingProgress(saved).eligible&&!palFindingProgress(saved).canPlay;useEffect(()=>{if(focused&&!finishing.current){if(locked)navigation.replace('LaunchUnlock');else if(status.kind!=='ready'||(!preparing&&!saved.daily.active))navigation.popTo('Main',{screen:'Home'});}},[status.kind,saved.daily.active,navigation,focused,preparing,locked]);if(!q||(!preparing&&!saved.daily.active)||status.kind!=='ready'||locked)return <Screen><ActivityIndicator color={BLUE}/></Screen>;const typingMatches=saved.launch?0:playAnswerCount(answer,q.id,profile.ageBand,saved.daily,saved.blocked,knownConnectionIds(saved.social,profile.ageBand,saved.blocked));
  function submit(){if(finishing.current||!answer.trim())return;if(preparing){try{const draft=answerInvitePreparation(saved,index,answer),next=index<2?submitInvitePreparation(draft,index):finishInvitePreparation(draft);if(index===2)finishing.current=true;setSaved(next);if(index<2)navigation.push('Play',{index:index+1,invite:true});else navigation.reset({index:1,routes:[{name:'Main'},{name:'LaunchUnlock'}]});}catch(e){Alert.alert('Your invite',(e as Error).message);}return;}if(index<2){try{const daily=submitDaily(saved.daily,q.id);setSaved(s=>({...s,daily}));navigation.push('Play',{index:index+1});}catch{navigation.popTo('Main',{screen:'Home'});}return;}const missing=saved.daily.active!.ids.findIndex(id=>!saved.daily.active!.answers[id]?.trim());if(missing>=0){navigation.replace('Play',{index:missing});return;}try{const next=saved.launch?finishLaunchPlay(saved):completeDemoPlay(saved);finishing.current=true;setSaved(next);navigation.reset({index:1,routes:[{name:'Main'},{name:saved.launch&&profile.ageBand==='10-12'?'LaunchReady':'Matching'}]});}catch{navigation.popTo('Main',{screen:'Home'});}}
  return <Screen><View className="gap-3"><Copy small>{index+1} / 3 · {PLAY_CATEGORIES.find(c=>c.id===saved.daily.active?.categoryId)?.name??(saved.launch?.globalPlay&&!preparing?'Global play':'Your three')}</Copy><View className="flex-row gap-2">{questions.map((q,i)=><View key={q.id} className={`h-1 flex-1 rounded-full ${i<=index?'bg-brand':'bg-line'}`}/>)}</View></View><View className="flex-1 min-h-[120px] justify-center py-3"><Text accessibilityRole="header" className="text-[36px] leading-[42px] font-semibold tracking-[-1px] text-ink">{q.prompt}</Text></View><View className="gap-3"><TextInput accessibilityLabel="Your answer" placeholder="Type your answer…" placeholderTextColor="#D0DEC3" value={answer} maxLength={40} onChangeText={text=>setSaved(s=>preparing?answerInvitePreparation(s,index,text):({...s,daily:answerDaily(s.daily,q.id,text)}))} onSubmitEditing={submit} returnKeyType={index===2?'done':'next'} autoCorrect={false} className="text-[29px] font-medium text-brand border-b-2 border-line py-3"/><View className="flex-row justify-between"><Copy small>{saved.launch?'Your own answer':profile.ageBand==='10-12'?'Private play':'Any answer works'}</Copy><Copy small>{answer.length}/40</Copy></View>{hasIdea(q.id)&&<View className="min-h-[44px] justify-center">{idea?<Text className="text-base text-brand">✧ <Text className="font-semibold">{idea}</Text></Text>:<Pressable accessibilityRole="button" disabled={remaining===0} onPress={()=>setIdeas(requestIdea(ideas,q.id).usage)} className="min-h-[44px] flex-row items-center justify-between"><Text className={`text-base text-brand ${remaining===0?'opacity-40':''}`}>✧ Need an idea?</Text><Copy small>{remaining?`${remaining} left this week`:'Resets Monday'}</Copy></Pressable>}</View>}<CTA label={index===2?(preparing?'Create my challenge':saved.launch&&profile.ageBand!=='10-12'?'Find my pal':saved.launch?'Save my answers':profile.ageBand==='10-12'?JOURNEY_COPY.privateReveal:JOURNEY_COPY.reveal):'Next'} disabled={!answer.trim()} onPress={submit}/></View></Screen>;
}
