function SpotCheckInScreen({route,navigation}:NativeStackScreenProps<Root,'SpotCheckIn'>){const {saved,now}=useStore(),change=useVisitChange(),{countryId,visitId}=route.params;if(!canUseCityBoard(saved,countryId))return <Screen><Title>Discover this city first.</Title></Screen>;return <NativeSpotCheckIn state={saved} now={now} id={countryId} onCheckIn={spotId=>{change(s=>checkInAtSpot(s,countryId,spotId,new Date(),visitId));navigation.replace('SpotPeople',{countryId,spotId});}}/>;}
function SpotPeopleScreen({route,navigation}:NativeStackScreenProps<Root,'SpotPeople'>){const {saved,now}=useStore(),change=useVisitChange(),{countryId,spotId}=route.params;if(!canUseCityBoard(saved,countryId)||!citySpot(countryId,spotId))return <Screen><Title>Spot unavailable.</Title></Screen>;return <NativeSpotPeople state={saved} now={now} id={countryId} spotId={spotId} onMeet={visitorId=>navigation.navigate('CityMeetPlan',{countryId,visitorId})} onLeave={()=>{try{change(s=>leaveCityVisit(s,currentCityVisit(s,countryId)!.id));}catch(e){Alert.alert('Check out',(e as Error).message);}}} onChange={()=>navigation.replace('SpotCheckIn',{countryId})} onCheckIn={()=>navigation.replace('SpotCheckIn',{countryId})}/>;}

function PalScreen({route}:NativeStackScreenProps<Root,'Pal'>){const {saved,now,setSetup}=useStore(),nav=useNavigation<Nav>(),play=usePlay(),openCheckIn=useCityMeetupOpen(),change=useSocialChange(),photos=usePhotoActions(),id=route.params.peerId,p=palFor(saved,id);if(!p)return <Screen><Title>Pal unavailable.</Title></Screen>;return <NativePalDetail onFavorite={id=>photos.safe(s=>toggleCityPhotoSaved(s,id))} state={saved} now={now} id={id} onPlay={()=>saved.launch?play(id):hasDailyProgress(saved.daily)?play():nav.navigate('Categories',{peerId:id})} onPhotos={(countryId,photoId)=>nav.navigate('CityPhotos',{countryId,photoId})} onCity={countryId=>nav.navigate('Country',{countryId})} onChat={()=>{if(!palFor(saved,id)?.chatUnlocked)return;change(s=>startDemoChat(s.social,id,s.profile!.ageBand,s.blocked));nav.navigate('PalChat',{peerId:id});}} onPlan={countryId=>saved.launch?openCheckIn(countryId):nav.navigate('PlanVisit',{countryId})} onMeet={()=>nav.navigate('PalMeeting',{peerId:id})} onEditProfile={()=>{setSetup(createSetupProfile(saved.profile!));nav.navigate('Setup');}}/>;}
function PalChatScreen({route}:NativeStackScreenProps<Root,'PalChat'>){const {saved}=useStore(),nav=useNavigation<Nav>(),change=useSocialChange(),id=route.params.peerId;if(!palFor(saved,id)?.chatUnlocked)return <Screen><Title>Match 5 times to chat.</Title></Screen>;return <NativePalChat state={saved} id={id} onSend={body=>change(s=>sendDemoMessage(s.social,id,s.profile!.ageBand,body,s.blocked))} onMeet={()=>nav.navigate('PalMeeting',{peerId:id})}/>;}
function PalMeetingScreen({route}:NativeStackScreenProps<Root,'PalMeeting'>){const {saved,now}=useStore(),change=useSocialChange(),visits=useVisitChange(),id=route.params.peerId,p=palFor(saved,id);if(!p||!isAdult(saved.profile!.ageBand))return <Screen><Title>Meeting unavailable.</Title></Screen>;return <NativePalMeeting state={saved} now={now} id={id} onCheckIn={spot=>visits(s=>checkInAtSpot(s,p.countryId,spot))} onShare={(spot,when)=>change(s=>sharePalMeeting(s,id,spot,meetingDateTime(when.split('T')[0],when.split('T')[1],countryById(p.countryId)!.timeZone)))} onRespond={(plan,accept)=>change(s=>respondPalMeeting(s,plan,accept))}/>;}


function useLaunchActions(){
 const {saved,setSaved}=useStore(),nav=useNavigation<Nav>(),play=usePlay(),lock=useRef(false);
 async function change(action:(s:PreviewState)=>PreviewState){const next=seedGlobalPals(action(saved));try{await AsyncStorage.setItem(KEY,JSON.stringify(next));}catch{throw new Error('Couldn’t save. Remove an older photo or free some device storage.');}setSaved(next);return next;}
 async function safe(action:(s:PreviewState)=>PreviewState){if(lock.current)return;lock.current=true;try{await change(action);}catch(e){Alert.alert('Your passport',(e as Error).message);}finally{lock.current=false;}}
 async function invite(){if(lock.current)return;if(saved.profile?.ageBand==='10-12'){nav.navigate('Main',{screen:'Cities'});return;}if(!hasInviteAnswers(saved)){await prepare();return;}lock.current=true;try{const invite=await makeFriendInvite(saved,nativeChallengeCrypto);await change(s=>rememberInvite(s,invite));nav.navigate('LaunchInvite',{inviteId:invite.id});}catch(e){Alert.alert('Friend challenge',(e as Error).message);}finally{lock.current=false;}}
 async function prepare(){if(lock.current)return;lock.current=true;try{const next=await change(s=>beginInvitePreparation(s));nav.navigate('Play',{index:invitePreparationIndex(next),invite:true});}catch(e){Alert.alert('Your invite',(e as Error).message);}finally{lock.current=false;}}
 return {change,safe,invite,prepare};
}
function LaunchReadyScreen(){const {saved}=useStore(),nav=useNavigation<Nav>(),launch=useLaunchActions();return <NativeLaunchReady state={saved} onInvite={()=>void launch.invite()} onGuide={()=>nav.navigate('Main',{screen:'Cities'})}/>;}
function LaunchInviteScreen({route}:NativeStackScreenProps<Root,'LaunchInvite'>){const {saved}=useStore(),nav=useNavigation<Nav>(),invite=saved.launch?.invites.find(i=>i.id===route.params.inviteId);return invite?<NativeLaunchInvite invite={invite} onBack={()=>nav.popTo('Main',{screen:'Home'})}/>:<Screen><Title>Start with your 3.</Title></Screen>;}
function LaunchGuideScreen({route}:NativeStackScreenProps<Root,'Guide'>){const {saved}=useStore(),launch=useLaunchActions(),openCheckIn=useCityMeetupOpen(),id=route.params.countryId;return <NativeLaunchGuide key={id} state={saved} onCheckIn={()=>openCheckIn(id)} id={id} onSave={()=>void launch.safe(s=>toggleGuide(s,id))} onPlace={place=>void launch.safe(s=>toggleGuidePlace(s,place))}/>;}
function LaunchPostcardsScreen({route}:NativeStackScreenProps<Root,'LaunchPostcards'>){const {saved}=useStore(),launch=useLaunchActions(),nav=useNavigation<Nav>();return <NativeLaunchPostcards initialImport={!!route.params?.import} state={saved} onPlay={()=>void launch.invite()} onCollect={async reply=>{await launch.change(s=>collectPostcard(s,reply));nav.navigate('LaunchUnlock');}}/>;}
function LaunchMomentsScreen(){const {saved}=useStore(),nav=useNavigation<Nav>(),launch=useLaunchActions(),photos=usePhotoActions();return <NativeLaunchPhotos state={saved} onFavorite={id=>photos.safe(s=>togglePhotoFavorite(s,id).photos)} onCapture={()=>nav.navigate('Camera')} onRemove={id=>void launch.safe(s=>removeLaunchMoment(s,id))}/>;}

function LaunchUnlockScreen({route}:NativeStackScreenProps<Root,'LaunchUnlock'>){const {saved,now}=useStore(),nav=useNavigation<Nav>(),launch=useLaunchActions(),play=usePlay();return <NativeLaunchUnlock state={saved} now={now} autoPreview={!!route.params?.demo} onSimulate={async()=>{await launch.change(s=>simulatePalUnlock(s));}} onResetPreview={async()=>{await launch.change(resetPalUnlock);nav.popTo('Main',{screen:'Home'});}} onPrepare={()=>void launch.prepare()} onInvite={()=>void launch.invite()} onPlay={play} onExplore={()=>nav.navigate('Main',{screen:'Cities'})} onImport={()=>nav.navigate('LaunchPostcards',{import:true})}/>;}

function useCityMeetupOpen(){const {saved,setSaved}=useStore(),nav=useNavigation<Nav>();return (countryId?:CountryId)=>{if(saved.cityMeetup?.checkIn)setSaved(s=>({...s,cityMeetup:s.cityMeetup?viewMeetupRequests(s.cityMeetup):undefined}));nav.navigate('CityCheckIn',{countryId});};}
function CityCheckInScreen({route,navigation}:NativeStackScreenProps<Root,'CityCheckIn'>){const {saved,now}=useStore(),launch=useLaunchActions();if(!saved.profile||saved.profile.ageBand==='10-12')return <Screen><Title>Your private world.</Title></Screen>;return <NativeCityMeetupFlow profile={saved.profile} session={saved.cityMeetup} now={now} initialCity={route.params?.countryId} onChange={async next=>{await launch.change(s=>({...s,cityMeetup:next}));}} onExit={()=>navigation.popTo('Main',{screen:'Cities'})}/>;}

function PalVisitMeetScreen({route,navigation}:NativeStackScreenProps<Root,'PalVisitMeet'>){const {saved,now}=useStore(),launch=useLaunchActions();return <NativeHomeVisitMeet state={saved} now={now} peerId={route.params.peerId} onChange={async action=>{await launch.change(action);}} onBack={()=>navigation.popTo('Main',{screen:'Home'})}/>;}
